<?php namespace App\Livewire\Admin; use App\Models\Stall; use App\Models\User; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageStalls extends Component { use AuthorizesRequests; public string $user_id = ''; public string $name = ''; public string $location = ''; public function createStall(): void { $this->authorize('create', Stall::class); $validated = $this->validate(['user_id' => ['required', 'exists:users,id', 'unique:stalls,user_id'], 'name' => ['required', 'string', 'max:255'], 'location' => ['required', 'string', 'max:255']]); Stall::create(['user_id' => $validated['user_id'], 'name' => strip_tags($validated['name']), 'location' => strip_tags($validated['location']), 'status' => 'active']); $this->reset(['user_id', 'name', 'location']); session()->flash('status', 'New stall registered.'); } public function toggleStatus(int $id): void { $stall = Stall::findOrFail($id); $this->authorize('update', $stall); $stall->update(['status' => $stall->status === 'active' ? 'inactive' : 'active']); } public function render() { $availableVendors = User::where('role', 'vendor')->doesntHave('stall')->get(); return view('livewire.admin.manage-stalls', ['stalls' => Stall::with('user')->get(), 'vendors' => $availableVendors]); } }